#include <stdio.h>
#include <stdlib.h>

static int par[100005];

static int find(int x){
    int r = x;
    while (par[r] != r) r = par[r];
    while (par[x] != r) { int nx = par[x]; par[x] = r; x = nx; }
    return r;
}

int main(void){
    int n, m;
    long long k;
    if (scanf("%d %d %lld", &n, &m, &k) != 3) return 0;

    int *ea = (int*)malloc(sizeof(int) * m);
    int *eb = (int*)malloc(sizeof(int) * m);
    int *et = (int*)malloc(sizeof(int) * m);

    for (int i = 0; i < m; i++)
        scanf("%d %d %d", &ea[i], &eb[i], &et[i]);

    for (int i = 1; i <= n; i++) par[i] = i;

    int impossible = 0;

    /* Primeiro adiciona todas as hidrovias: elas existiam há K anos e não podem ser removidas.
       Se duas hidrovias fecharem um ciclo, é impossível tornar a rede simples. */
    for (int i = 0; i < m; i++){
        if (et[i] == 1){
            int ra = find(ea[i]), rb = find(eb[i]);
            if (ra == rb){ impossible = 1; break; }
            par[ra] = rb;
        }
    }

    long long removed = 0;
    if (!impossible){
        /* Rodovias: mantém as que conectam componentes distintas,
           remove (conta) as que fechariam ciclo. */
        for (int i = 0; i < m; i++){
            if (et[i] == 2){
                int ra = find(ea[i]), rb = find(eb[i]);
                if (ra == rb) removed++;
                else par[ra] = rb;
            }
        }
    }

    printf("%c\n", (impossible || removed > k) ? 'N' : 'S');

    free(ea); free(eb); free(et);
    return 0;
}
